import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import { useGlobal } from "../context/GlobalContext";

const styles = {
  container: {
    fontFamily: 'Arial, sans-serif',
    padding: '20px',
    background: 'linear-gradient(to bottom right, #6a5acd, #9370db)',
    borderRadius: '15px',
    boxShadow: '0 10px 30px rgba(0, 0, 0, 0.3)',
    maxWidth: '90%',
    margin: '40px auto',
    color: '#fff',
    fontSize: '1.6rem',
  },
  header: {
    marginBottom: '20px',
    fontSize: '2em',
    fontWeight: 'bold',
    textAlign: 'center',
    color: '#fff',
  },
  tableContainer: {
    overflowX: 'auto',
    borderRadius: '10px',
    boxShadow: '0 10px 20px rgba(0, 0, 0, 0.15)',
  },
  table: {
    width: '100%',
    minWidth: '600px',
    borderCollapse: 'collapse',
    backgroundColor: '#fff',
  },
  tableHeader: {
    backgroundColor: '#6c63ff',
    color: '#fff',
    padding: '10px',
    fontSize: '1em',
    fontWeight: 'bold',
    textAlign: 'center',
  },
  tableData: {
    padding: '12px',
    fontSize: '0.9em',
    color: '#333',
    textAlign: 'center',
    borderBottom: '1px solid #ddd',
  },
  loadMoreButton: {
    display: 'block',
    margin: '20px auto',
    padding: '10px 20px',
    backgroundColor: '#4b0082',
    color: '#fff',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    fontSize: '1.2em',
  },
};

function TestResults() {
  const { API_URL } = useGlobal();
  const { testid } = useParams();
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [totalPages, setTotalPages] = useState(1);

  const fetchResults = async (pageNum = 1) => {
    setLoading(true);
    try {
      const token = document.cookie
        .split('; ')
        .find(row => row.startsWith('x-auth-token='))
        ?.split('=')[1];

      const response = await fetch(`${API_URL}/api/studentmarks/marks/${testid}?page=${pageNum}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': token || '',
        },
      });

      const data = await response.json();
      const fetchedResults = data.data || [];

      // Update total pages
      setTotalPages(data.totalPages);

      if (fetchedResults.length === 0 || pageNum >= data.totalPages) {
        setHasMore(false);
      }

      // Append new results without duplicates
      setResults(prevResults => {
        const existingIds = new Set(prevResults.map(result => result._id));
        const newResults = fetchedResults.filter(result => !existingIds.has(result._id));
        return [...prevResults, ...newResults];
      });
    } catch (error) {
      console.error("Error fetching test results:", error);
      toast.error("Failed to load test results.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchResults(page);
  }, [testid, page]);

  const loadMore = () => {
    if (page < totalPages) {
      setPage(prevPage => prevPage + 1);
    }
  };

  if (loading && page === 1) {
    return <div className="loader-container">
      <div className="loader"></div>
    </div>;
  }

  if (!results.length) {
    return (
      <div style={styles.container}>
        <h1>Results Not Declared</h1>
        <p>The results for this test are not yet declared. Please check back later.</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Test Results</h1>
      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={styles.tableHeader}>Student Name</th>
              <th style={styles.tableHeader}>Test Title</th>
              <th style={styles.tableHeader}>Date</th>
              <th style={styles.tableHeader}>Subject</th>
              <th style={styles.tableHeader}>Score</th>
              <th style={styles.tableHeader}>Percentage</th>
              <th style={styles.tableHeader}>Status</th>
              <th style={styles.tableHeader}>Attempted At</th>
            </tr>
          </thead>
          <tbody>
            {results.map((result, index) => (
              <tr key={result._id || index}>
                <td style={styles.tableData}>{result.studentId.name}</td>
                <td style={styles.tableData}>{result.testTitle}</td>
                <td style={styles.tableData}>{new Date(result.testDate).toLocaleDateString()}</td>
                <td style={styles.tableData}>{result.subject}</td>
                <td style={styles.tableData}>{`${result.marksObtained} / ${result.totalMarks}`}</td>
                <td style={styles.tableData}>
                  {((result.marksObtained / result.totalMarks) * 100).toFixed(2)}%
                </td>
                <td style={styles.tableData}>{result.status}</td>
                <td style={styles.tableData}>{new Date(result.attemptedAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {hasMore && page < totalPages && (
        <button
          style={styles.loadMoreButton}
          onClick={loadMore}
          disabled={loading}
        >
          {loading ? "Loading..." : "Load More"}
        </button>
      )}
    </div>
  );
}

export default TestResults;
