import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { Link } from 'react-router-dom';
import { useGlobal } from "../context/GlobalContext";

const StudentListByBatch = () => {
    const { API_URL } = useGlobal()

    const [students, setStudents] = useState([]);
    const [selectedStatus, setSelectedStatus] = useState('active');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);
    const [searchQuery, setSearchQuery] = useState('');

    const getTokenFromCookies = () => {
        const cookieValue = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
        return cookieValue ? cookieValue.split('=')[1] : null;
    };

    const token = getTokenFromCookies();

    // Fetch students based on current filters
    const fetchStudents = async (page = 1, isSearch = false) => {
        setLoading(true);
        setError('');
        
        try {
            const url = isSearch && searchQuery 
                ? `${API_URL}/api/users/search-users?role=student&status=${selectedStatus}&page=${page}&query=${searchQuery}`
                : `${API_URL}/api/users/profiles/student?status=${selectedStatus}&page=${page}`;
            
            const response = await axios.get(url, {
                headers: { 'x-auth-token': token }
            });

            setStudents(prevStudents => {
                const newStudents = response.data.users;
                return isSearch 
                    ? newStudents // Replace students on search
                    : [...prevStudents, ...newStudents.filter(student => 
                        !prevStudents.some(prevStudent => prevStudent._id === student._id)
                    )];
            });

            setTotalPages(response.data.totalPages);
        } catch (err) {
            console.error("Error fetching students:", err);
            setError("Failed to load student data");
            setStudents([]);
        } finally {
            setLoading(false);
        }
    };

    // UseEffect to fetch students whenever status or page changes
    useEffect(() => {
        fetchStudents(currentPage, false); // Initial fetch for all students
    }, [selectedStatus, token, currentPage]);

    const handleStatusChange = (e) => {
        const status = e.target.value;
        setSelectedStatus(status);
        setStudents([]); // Reset students when status changes
        setCurrentPage(1); // Reset page to 1
        setError('');
        setTotalPages(1); // Reset total pages to reload data
    };

    const handleSearchChange = (e) => {
        setSearchQuery(e.target.value);
    };

    const handleSearchButtonClick = () => {
        setStudents([]); // Clear current students to load new results
        setCurrentPage(1); // Reset to first page
        fetchStudents(1, searchQuery.length > 0); // Fetch students based on search query
    };

    const handleStudentStatusChange = async (studentId, newStatus) => {
        setLoading(true);
        try {
            await axios.put(`${API_URL}/api/auth/status/${studentId}`, { status: newStatus }, {
                headers: { 'x-auth-token': token }
            });
            setStudents((prevStudents) =>
                prevStudents.map((student) =>
                    student._id === studentId ? { ...student, status: newStatus } : student
                )
            );
            toast.success('Status updated successfully!');
        } catch (err) {
            console.error("Error updating status:", err);
            toast.error('Failed to update status');
        } finally {
            setLoading(false);
        }
    };

    const loadMoreStudents = () => {
        if (currentPage < totalPages) {
            setCurrentPage(prevPage => prevPage + 1);
        }
    };

    const totalPendingFee = students.reduce((total, student) => total + (student.pendingFee || 0), 0);

    return (
        <div className="container mt-5 attendance-container">
            <h2 className="text-center mb-4 title">Students List by Status</h2>

            <div className="mb-3 date-container">
                <label htmlFor="status" className="form-label">Select Status:</label>
                <select
                    id="status"
                    className="form-control date-input"
                    value={selectedStatus}
                    onChange={handleStatusChange}
                >
                    <option value="active">Active</option>
                    <option value="pending">Pending</option>
                    <option value="completed">Completed</option>
                    <option value="re-enrolled">Re-enrolled</option>
                    <option value="absconded">Absconded</option>
                    <option value="postponed">Postponed</option>
                    <option value="suspended">Suspended</option>
                    <option value="withdrawn">Withdrawn</option>
                </select>
            </div>

            <div className="mb-3">
                <input
                    type="text"
                    className="form-control"
                    placeholder="Search by name..."
                    onChange={handleSearchChange}
                    value={searchQuery}
                />
                <button className="btn btn-primary mt-2" onClick={handleSearchButtonClick}>
                    Search
                </button>
            </div>

            {error ? (
                <p className="text-danger">{error}</p>
            ) : loading ? (
                <div className="loader-container">
                <div className="loader"></div>
              </div>
            ) : students.length > 0 ? (
                <>
                    <table className="table attendance-table">
                        <thead>
                            <tr>
                                <th>Student Name</th>
                                <th>Contact No.</th>
                                <th>Pending Fee (INR)</th>
                                <th>Status</th>
                            </tr>
                        </thead>
                        <tbody>
                            {students.map((student) => (
                                <tr key={student._id}>
                                    <td><Link style={{ color: "black" }} to={`/loggedin/profile/${student._id}`}>{student.name}</Link></td>
                                    <td><Link style={{ color: "black" }} to={`/tel:${student.personalContactNumber}`}>{student.personalContactNumber}</Link></td>
                                    <td>₹{student.pendingFee}</td>
                                    <td>
                                        <select
                                            value={student.status}
                                            onChange={(e) => handleStudentStatusChange(student._id, e.target.value)}
                                            className="form-control"
                                        >
                                            <option value="active">Active</option>
                                            <option value="pending">Pending</option>
                                            <option value="completed">Completed</option>
                                            <option value="re-enrolled">Re-enrolled</option>
                                            <option value="absconded">Absconded</option>
                                            <option value="postponed">Postponed</option>
                                            <option value="suspended">Suspended</option>
                                            <option value="withdrawn">Withdrawn</option>
                                        </select>
                                    </td>
                                </tr>
                            ))}
                            <tr>
                                <td colSpan="2"><strong>Total Pending Fee</strong></td>
                                <td colSpan="2"><strong>₹{totalPendingFee}</strong></td>
                            </tr>
                        </tbody>
                    </table>
                    {currentPage < totalPages && (
                        <div className="text-center">
                            <button className="btn btn-primary" onClick={loadMoreStudents}>
                                Load More
                            </button>
                        </div>
                    )}
                </>
            ) : (
                <p className="text-center">No student data found</p>
            )}

            <ToastContainer />
            <style>
                {`
                    .loader-container {
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        height: 100px;
                    }
                `}
            </style>
        </div>
    );
};

export default StudentListByBatch;
