import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Cookies from 'js-cookie';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const StudyMaterialForm = () => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    subject: 'Math',
    batch: '',
    materialType: 'Notes',
    fileLink: '',
    fileType: '',
    ytVideo: '',
  });
  const [file, setFile] = useState(null);
  const [batches, setBatches] = useState([]);

  useEffect(() => {
    const fetchBatches = async () => {
      try {
        toast.loading('Fetching batches...', { toastId: 'fetch-batches' });
        const token = Cookies.get('x-auth-token');
        const response = await axios.get('http://localhost:5000/api/standard/batch', {
          headers: { 'x-auth-token': token },
        });
        setBatches(response.data);
        toast.update('fetch-batches', {
          render: 'Batches fetched successfully!',
          type: 'success',
          isLoading: false,
          autoClose: 2000,
        });
      } catch (error) {
        toast.update('fetch-batches', {
          render: 'Failed to fetch batches',
          type: 'error',
          isLoading: false,
          autoClose: 2000,
        });
      }
    };

    fetchBatches();
  }, []);

  const handleFileChange = (e) => setFile(e.target.files[0]);
  const handleInputChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    toast.loading('Uploading study material...', { toastId: 'upload-material' });

    try {
      let fileLink = formData.ytVideo;
      if (formData.materialType !== 'YT-Videos' && file) {
        const formDataFile = new FormData();
        formDataFile.append('file', file);
        const token = Cookies.get('x-auth-token');

        const fileUploadResponse = await axios.post('http://localhost:5000/api/users/upload', formDataFile, {
          headers: { 'Content-Type': 'multipart/form-data', 'x-auth-token': token },
        });
        fileLink = fileUploadResponse.data.fileLink;
      }

      const studyMaterialData = {
        ...formData,
        fileLink,
        fileType: formData.materialType === 'YT-Videos' ? 'video/mp4' : file?.type,
      };

      const token = Cookies.get('x-auth-token');
      await axios.post('http://localhost:5000/api/studymaterial/', studyMaterialData, {
        headers: { 'x-auth-token': token },
      });

      toast.update('upload-material', {
        render: 'Study material uploaded successfully!',
        type: 'success',
        isLoading: false,
        autoClose: 2000,
      });
      setFormData({
        title: '',
        description: '',
        subject: 'Math',
        batch: '',
        materialType: 'Notes',
        fileLink: '',
        fileType: '',
        ytVideo: '',
      });
      setFile(null);
    } catch (error) {
      toast.update('upload-material', {
        render: error.response?.data?.message || 'An error occurred',
        type: 'error',
        isLoading: false,
        autoClose: 2000,
      });
    }
  };

  return (
    <div className="study-material-form-container">
      <h2>Upload Study Material</h2>
      <form className="study-material-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Title:</label>
          <input type="text" name="title" value={formData.title} onChange={handleInputChange} required />
        </div>

        <div className="form-group">
          <label>Description:</label>
          <textarea name="description" value={formData.description} onChange={handleInputChange}></textarea>
        </div>

        <div className="form-group">
          <label>Subject:</label>
          <input type="text" name="subject" value={formData.subject} onChange={handleInputChange} required />
        </div>

        <div className="form-group">
          <label>Batch:</label>
          <select name="batch" value={formData.batch} onChange={handleInputChange} required>
            <option value="">Select Batch</option>
            {batches.map((batch) => (
              <option key={batch._id} value={batch._id}>
                {batch.name} - {batch.standard.name}
              </option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>Material Type:</label>
          <select name="materialType" value={formData.materialType} onChange={handleInputChange} required>
            <option value="Notes">Notes</option>
            <option value="YT-Videos">YT-Videos</option>
            <option value="Previous-question-papers">Previous-question-papers</option>
            <option value="E-Books">E-Books</option>
          </select>
        </div>

        {formData.materialType !== 'YT-Videos' ? (
          <div className="form-group">
            <label>File:</label>
            <input type="file" onChange={handleFileChange} required />
          </div>
        ) : (
          <div className="form-group">
            <label>YouTube Video Link:</label>
            <input type="url" name="ytVideo" value={formData.ytVideo} onChange={handleInputChange} required />
          </div>
        )}

        <button type="submit" className="submit-btn">
          Upload Study Material
        </button>
      </form>
      <ToastContainer />
    </div>
  );
};

export default StudyMaterialForm;
