import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import { useGlobal } from "../context/GlobalContext";
const PaymentHistory = () => {
  const { role,API_URL } = useGlobal()
  const { studentId } = useParams();
  const [payments, setPayments] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [showAddForm, setShowAddForm] = useState(false);
  const [showUpdateForm, setShowUpdateForm] = useState(false); // New state for showing update form
  const [selectedPayment, setSelectedPayment] = useState(null); // New state for selected payment to edit
  const [newPayment, setNewPayment] = useState({
    student: studentId,
    amount: "",
    method: "cash",
    paymentGateway: "manual",
    memo: "",
  });
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const fetchPayments = async (page = 1, isLoadMore = false) => {
    setLoading(true);
    try {
      const token = document.cookie
        .split("; ")
        .find((row) => row.startsWith("x-auth-token="))
        ?.split("=")[1];

      const response = await axios.get(
        `${API_URL}/api/payments/fee/all/${studentId}`,
        {
          headers: { "x-auth-token": token },
          params: { page, limit: 10 },
        }
      );

      setPayments((prev) =>
        isLoadMore ? [...prev, ...response.data.FeePayments] : response.data.FeePayments
      );
      setCurrentPage(response.data.currentPage);
      setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error("Error fetching payments:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPayments();
  }, [studentId]);

  const handleAddPayment = async () => {
    if (role !== 'admin') {
      return ''
    }
    setLoading(true);
    setErrorMessage("");
    try {
      const token = document.cookie
        .split("; ")
        .find((row) => row.startsWith("x-auth-token="))
        ?.split("=")[1];

      await axios.post(
        `${API_URL}/api/payments/fee/add`,
        { ...newPayment },
        { headers: { "x-auth-token": token } }
      );

      setShowAddForm(false);
      setNewPayment({ student: studentId, amount: "", method: "cash", paymentGateway: "manual", memo: "" });
      fetchPayments();
    } catch (error) {
      console.error("Error adding payment:", error);
      setErrorMessage(error.response.data.message);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdatePayment = async () => {
    if (!selectedPayment) return;
    setLoading(true);
    setErrorMessage("");
    try {
      const token = document.cookie
        .split("; ")
        .find((row) => row.startsWith("x-auth-token="))
        ?.split("=")[1];

      await axios.put(
        `${API_URL}/api/payments/fee/update/${selectedPayment._id}`,
        { ...selectedPayment },
        { headers: { "x-auth-token": token } }
      );

      setShowUpdateForm(false);
      setSelectedPayment(null);
      fetchPayments();
    } catch (error) {
      setErrorMessage(error.response.data.message);

    } finally {
      setLoading(false);
    }
  };

  const handleDeletePayment = async (id) => {
    if (role !== 'admin') {
      return ''
    }
    setLoading(true);
    try {
      const token = document.cookie
        .split("; ")
        .find((row) => row.startsWith("x-auth-token="))
        ?.split("=")[1];

      await axios.delete(`${API_URL}/api/payments/fee/delete/${id}`, {
        headers: { "x-auth-token": token },
      });

      fetchPayments();
    } catch (error) {
      console.error("Error deleting payment:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      {loading && (
        <div className="loader-overlay">
            <div className="loader-container">
      <div className="loader"></div>
    </div>
        </div>
      )}
      <div className={`content ${loading ? 'blur' : ''}`}>
        <div className="header">
          <h1>Fee Payment History</h1>
          <br />
          {role === 'admin' ?
          <button
            className="button addButton"
            onClick={() => {
              setShowAddForm(!showAddForm);
              setShowUpdateForm(false);
            }}
          >
            <i className="fas fa-plus" /> New
          </button>:""}
          <br />
          <br />
        </div>
        {role === 'admin' ? <>
          {showAddForm && (
            <div className="form">
              <h3>Add New Payment</h3>
              {errorMessage && <p style={{ color: 'red' }}>{errorMessage}</p>}
              <input
                className="input"
                type="number"
                placeholder="Amount"
                value={newPayment.amount}
                onChange={(e) => {
                  const value = e.target.value;
                  setNewPayment({ ...newPayment, amount: value });
                  if (value < 1) {
                    setErrorMessage("Amount must be greater than 0.");
                  } else {
                    setErrorMessage("");
                  }
                }}
              />
              <input
                className="input"
                type="text"
                placeholder="Memo"
                value={newPayment.memo}
                onChange={(e) => setNewPayment({ ...newPayment, memo: e.target.value })}
              />
              <select
                className="input"
                value={newPayment.method}
                onChange={(e) => setNewPayment({ ...newPayment, method: e.target.value })}
              >
                <option value="cash">Cash</option>
                <option value="card">Card</option>
                <option value="bank_transfer">Bank Transfer</option>
                <option value="UPI">UPI</option>
              </select>
              <select
                className="input"
                value={newPayment.paymentGateway}
                onChange={(e) => setNewPayment({ ...newPayment, paymentGateway: e.target.value })}
              >
                <option value="manual">Manual</option>
              </select>
              <button
                className="button addButton"
                onClick={handleAddPayment}
                disabled={loading || newPayment.amount < 1}
              >
                Add Payment
              </button>
            </div>
          )}
        </> : ''}
        {role === 'admin' ? <>
        {showUpdateForm && selectedPayment && (
          <div className="form">
            <h3>Update Payment</h3>
            {errorMessage && <p style={{ color: 'red' }}>{errorMessage}</p>}
            <input
              className="input"
              type="number"
              placeholder="Amount"
              value={selectedPayment.amount}
              onChange={(e) => {
                const value = e.target.value;
                setSelectedPayment({ ...selectedPayment, amount: value });
                if (value < 1) {
                  setErrorMessage("Amount must be greater than 0.");
                } else {
                  setErrorMessage("");
                }
              }}
            />
            <input
              className="input"
              type="text"
              placeholder="Memo"
              value={selectedPayment.memo}
              onChange={(e) => setSelectedPayment({ ...selectedPayment, memo: e.target.value })}
              />
            <select
              className="input"
              value={selectedPayment.method}
              onChange={(e) => setSelectedPayment({ ...selectedPayment, method: e.target.value })}
              >
              <option value="cash">Cash</option>
              <option value="card">Card</option>
              <option value="bank_transfer">Bank Transfer</option>
              <option value="UPI">UPI</option>
            </select>
            <button
              className="button addButton"
              onClick={handleUpdatePayment}
              disabled={loading || selectedPayment.amount < 1}
              >
              Update Payment
            </button>
          </div>
        )}
        </>:""}
        <table className="table">
          <thead>
            <tr>
              <th className="th">Payment Date</th>
              <th className="th">Method</th>
              <th className="th">Status</th>
              <th className="th">Amount</th>
              <th className="th">Memo</th>
        {role === 'admin' ? <>
              <th className="th">Actions</th>
        </>:""}
            </tr>
          </thead>
          <tbody>
            {payments.map((payment) => (
              <tr key={payment._id}>
                <td className="td">{new Date(payment.date).toLocaleString()}</td>
                <td className="td">{payment.method}</td>
                <td className="td">
                  <span
                    className={`status ${payment.status === "completed" ? "completed" : "pending"}`}
                  >
                    {payment.status}
                  </span>
                </td>
                <td className="td">
                  {payment.amount} {payment.currency}
                </td>
                <td className="td">{payment.memo || "N/A"}</td>
                {role === 'admin' ?
                <td className="td">
                  <button
                    className="button updateButton"
                    onClick={() => {
                      setSelectedPayment(payment);
                      setShowUpdateForm(true);
                      setShowAddForm(false);
                    }}
                  >
                    <i className="fas fa-edit" /> Edit
                  </button>
                  <button
                    className="button deleteButton"
                    onClick={() => handleDeletePayment(payment._id)}
                  >
                    <i className="fas fa-trash" /> Delete
                  </button>
                </td>
                :''}
              </tr>
            ))}
          </tbody>
        </table>
        {currentPage < totalPages && (
          <button
            className="button addButton"
            onClick={() => fetchPayments(currentPage + 1, true)}
            disabled={loading}
          >
            Load More
          </button>
        )}
      </div>
      <style>
        {`
          .loader-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: rgba(255, 255, 255, 0.8);
            z-index: 1000;
          }
          .content.blur {
            filter: blur(3px);
          }
        `}
      </style>
    </div>
  );
};

export default PaymentHistory;
