import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Cookies from 'js-cookie';
import { useGlobal } from "../context/GlobalContext";

const StudyMaterialList = ({ materialType }) => {
  const { role, API_URL, userProfile } = useGlobal();  // Access userProfile to get the logged-in user ID
  const [studyMaterials, setStudyMaterials] = useState([]);
  const [batches, setBatches] = useState([]);
  const [selectedBatch, setSelectedBatch] = useState('');
  const [loading, setLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedVideo, setSelectedVideo] = useState(null);

  // Fetch batches for non-student roles
  useEffect(() => {
    const fetchBatches = async () => {
      if (role === 'student') return;

      try {
        const token = Cookies.get('x-auth-token');
        const response = await axios.get(`${API_URL}/api/standard/batch`, {
          headers: { 'x-auth-token': token },
        });
        setBatches(response.data);
      } catch (error) {
        setErrorMessage('Failed to fetch batches.');
      } finally {
        setLoading(false);
      }
    };

    fetchBatches();
  }, [role, API_URL]);

  // Fetch study materials based on user role and selected batch
  useEffect(() => {
    const fetchStudyMaterials = async () => {
      setLoading(true);

      try {
        const token = Cookies.get('x-auth-token');
        let url = `${API_URL}/api/studymaterial`;

        // For student role, fetch without batch ID
        if (role === 'student') {
          url = `${url}/1?materialType=${materialType}`;
        } else {
          // For other roles, use selected batch
          if (!selectedBatch) {
            setLoading(false);
            return;
          }
          url = `${url}/${selectedBatch}?materialType=${materialType}`;
        }

        // Clear previous data before fetching new materials
        setStudyMaterials([]);
        setErrorMessage('');

        const response = await axios.get(url, {
          headers: { 'x-auth-token': token },
        });

        const materials = Array.isArray(response.data) ? response.data : [];
        setStudyMaterials(materials);

      } catch (error) {
        setErrorMessage('Failed to fetch study materials.');
      } finally {
        setLoading(false);
      }
    };

    if (selectedBatch || role === 'student') {
      fetchStudyMaterials();
    }
  }, [selectedBatch, materialType, role, API_URL]);

  const handleBatchChange = (e) => {
    setSelectedBatch(e.target.value);
    setStudyMaterials([]); // Clear previous study materials when batch changes
    setErrorMessage('');   // Clear any previous error message
  };

  const handleWatchVideo = (ytVideoUrl) => {
    setSelectedVideo(ytVideoUrl);
  };

  const closeVideoModal = () => {
    setSelectedVideo(null);
  };

  const handleDelete = async (materialId) => {
    const confirmDelete = window.confirm('Are you sure you want to delete this study material?');

    if (confirmDelete) {
      try {
        const token = Cookies.get('x-auth-token');
        await axios.delete(`${API_URL}/api/studymaterial/${materialId}`, {
          headers: { 'x-auth-token': token },
        });

        // Remove the deleted material from the list
        setStudyMaterials(studyMaterials.filter(material => material._id !== materialId));
      } catch (error) {
        setErrorMessage('Failed to delete study material.');
      }
    }
  };

  if (loading)
    return (
      <div className="loader-container">
        <div className="loader"></div>
      </div>
    );

  if (errorMessage) return <div className="error-message">{errorMessage}</div>;
  return (
    <div className="study-materials-container">
      <h2 className="page-title">Study Materials</h2>

      {role !== 'student' && (
        <div className="filters">
          <div className="filter-group">
            <label htmlFor="batch-select">Select Batch:</label>
            <select id="batch-select" onChange={handleBatchChange} value={selectedBatch}>
              <option value="">Select Batch</option>
              {batches.map((batch) => (
                <option key={batch._id} value={batch._id}>
                  {batch.name} - {batch.standard.name}
                </option>
              ))}
            </select>
          </div>
        </div>
      )}

      {studyMaterials.length === 0 ? (
        <p>No study materials found for the selected criteria.</p>
      ) : (
        <div className="study-materials-list">
          {studyMaterials.map((material) => (
            <div key={material._id} className="study-material-card">
              <h3 className="material-title">{material.title}</h3>
              <p className="material-description">{material.description}</p>
              <p className="material-subject">
                <strong>Subject:</strong> {material.subject}
              </p>
              <p className="material-type">
                <strong>Material Type:</strong> {material.materialType}
              </p>
              <div className="material-actions">
                {material.materialType === 'YT-Videos' ? (
                  <button className="watch-video-btn" onClick={() => handleWatchVideo(material.ytVideo)}>
                    Watch Video
                  </button>
                ) : (
                  <a href={material.filePath} className="material-link" target="_blank" rel="noopener noreferrer">
                    View {material.materialType === 'Previous-question-papers' ? 'Paper' : 'File'}
                  </a>
                )}

                {/* Check if the logged-in user is the uploader */}
                {role !== 'student' && userProfile && material.uploadedBy._id === userProfile._id && (
                  <>  
                  <button
                    className="delete-btn"
                    onClick={() => handleDelete(material._id)}
                    >
                    Delete
                  </button>
                    </>
                )}
              </div>
              <p className="material-uploaded">
                <em>Uploaded on: {new Date(material.createdAt).toLocaleDateString()}</em>
              </p>
            </div>
          ))}
        </div>
      )}

      {selectedVideo && (
        <div className="video-modal">
          <div className="video-modal-content">
            <button className="close-btn" onClick={closeVideoModal}>X</button>
            <iframe
              width="560"
              height="315"
              src={`https://www.youtube.com/embed/${new URL(selectedVideo).searchParams.get('v')}`}
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
              title="YouTube Video"
            ></iframe>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudyMaterialList;
