import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Cookies from 'js-cookie'; // Import the Cookies library
import { useGlobal } from '../context/GlobalContext';

const BannerUploader = () => {
  const { API_URL } = useGlobal();
  const [title, setTitle] = useState('');
  const [image, setImage] = useState(null);
  const [banners, setBanners] = useState([]);
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true); // New loader for fetching banners
  const [error, setError] = useState('');

  // Fetch banners once on initial load
  useEffect(() => {
    const fetchBanners = async () => {
      setFetching(true);
      try {
        const token = Cookies.get('x-auth-token'); // Extract token from cookies
        const response = await axios.get(`${API_URL}/api/banners`, {
          headers: { 'x-auth-token': token }, // Include token in headers
        });
        console.log('API Response:', response.data);
        setBanners(Array.isArray(response.data) ? response.data : []);
      } catch (err) {
        console.error('Error fetching banners:', err);
        setBanners([]); // Reset to empty array on error
      } finally {
        setFetching(false);
      }
    };

    fetchBanners();
  }, [API_URL]);

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title || !image) {
      setError('Please fill in all fields and select an image.');
      return;
    }
    setError('');
    setLoading(true);

    const formData = new FormData();
    formData.append('title', title);
    formData.append('image', image);

    try {
      const token = Cookies.get('x-auth-token'); // Extract token from cookies
      const response = await axios.post(`${API_URL}/api/banners/upload`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'x-auth-token': token, // Include token in headers
        },
      });

      // Clear the form fields after submission
      setTitle('');
      setImage(null);
      alert('Banner uploaded successfully!');
      setBanners((prevBanners) => [
        ...prevBanners,
        response.data.banner, // Assuming the response contains the uploaded banner data
      ]);
    } catch (err) {
      console.error('Error uploading banner:', err);
      setError('Failed to upload the banner.');
    } finally {
      setLoading(false);
    }
  };

  // Handle banner deletion
  const handleDelete = async (bannerId) => {
    const confirmDelete = window.confirm('Are you sure you want to delete this banner?');
    if (!confirmDelete) return;

    setLoading(true);
    const token = Cookies.get('x-auth-token'); // Extract token from cookies
    try {
      await axios.delete(`${API_URL}/api/banners/${bannerId}`, {
        headers: {
          'x-auth-token': token, // Include token in headers
        },
      });

      // Remove the deleted banner from the UI
      setBanners((prevBanners) => prevBanners.filter((banner) => banner._id !== bannerId));
      alert('Banner deleted successfully!');
    } catch (err) {
      console.error('Error deleting banner:', err);
      setError('Failed to delete the banner.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="banner-uploader">
      <h1>Upload Banner</h1>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="title">Title:</label>
          <input
            type="text"
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Enter banner title"
          />
        </div>
        <div className="form-group">
          <label htmlFor="image">Image:</label>
          <input
            type="file"
            id="image"
            onChange={(e) => setImage(e.target.files[0])}
            accept="image/*"
          />
        </div>
        {error && <p className="error-message">{error}</p>}
        <button type="submit" disabled={loading}>
          {loading ? 'Processing...' : 'Upload'}
        </button>
      </form>

      {fetching ? (
        <div className="loader-container">
          <div className="loader"></div>
        </div>
      ) : (
        <div className="banners-list">
          <h2>Uploaded Banners</h2>
          {Array.isArray(banners) && banners.length > 0 ? (
            <div className="banners-grid">
              {banners.map((banner) => (
                <div className="banner-card" key={banner._id}>
                  <img
                    src={`${banner.image}`}
                    alt={banner.title}
                    className="banner-image"
                  />
                  <p className="banner-title">{banner.title}</p>
                  <button
                    className="delete-button"
                    onClick={() => handleDelete(banner._id)} // Call handleDelete with banner ID
                    disabled={loading} // Disable the button if processing
                  >
                    {loading ? 'Deleting...' : 'Delete'}
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <p>No banners uploaded yet.</p>
          )}
        </div>
      )}
    </div>
  );
};

export default BannerUploader;
