import React, { useEffect, useState } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { useGlobal } from './context/GlobalContext';
import Cookies from 'js-cookie';

// Components
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Footer from './components/Footer';

// Pages
import Login from './pages/Login';
import DashBoard from './pages/Dashboard';
import MyProfile from './pages/MyProfile';
import Profile from './pages/Profile';
import Courses from './components/Courses';
import MarkStudentAttendance from './pages/MarkStudentAttendance';
import MarkStaffAttendance from './pages/MarkStaffAttendance';
import StudentAttendanceHistory from './pages/StudentAttandanceHistory';
import StaffAttendanceHistory from './pages/StaffAttandanceHistory';
import FeePaymentHistory from './pages/FeePaymentHistory';
import Register from './pages/Register';
import StudentListByBatch from './pages/StudentsList';
import StaffListByRole from './pages/StaffList';
import ManageBatches from './pages/ManageBatches';
import OnlineMCQTest from './pages/OnlineMCQTest';
import OnlineTestForm from './pages/OnlineTestForm';
import OfflineTestForm from './pages/OfflineTestForm';
import OnlinetestsList from './pages/OnlineTestsList';
import OfflinetestsList from './pages/OfflineTestsList';
import TestsResults from './pages/TestsResults';
import BulkAddStudentMarks from './pages/AddStudentMarksForm';
import OnlineFeePayment from './pages/OnlineFeePayment';
import StudyMaterialForm from './pages/StudyMaterialForm';
import StudyMaterialList from './pages/StudyMaterialLists';
import AccessDenied from './pages/AccessDenied';
import ComingSoon from './pages/ComingSoon';
import Quiz from './pages/Quiz';
import PageNotFound404 from './pages/PageNotFound404';
import ContactPage from './pages/ContactUs';
import BannerUploader from './pages/UploadSliderForm';

import './style.css';
import StandardBatchManagement from './pages/BatchStandard';

const App = () => {
  const navigate = useNavigate();
  const { isLoggedIn, isLoading, role, toggleDarkMode, darkMode } = useGlobal();
  const [sidebarActive, setSidebarActive] = useState(false);

  const token = Cookies.get('x-auth-token');

  useEffect(() => {
    if (!token) {
      navigate('/login');
    }
  }, [token, navigate]);

  const toggleSidebar = () => {
    setSidebarActive((prev) => !prev);
  };

  const closeSidebar = () => {
    setSidebarActive(false);
  };

  // If loading, show a loader
  if (isLoading) {
    return (
      <div style={{ textAlign: 'center', marginTop: '50px' }}>
        <h1>Loading...</h1>
      </div>
    );
  }

  return (
    <div>
      {isLoggedIn && (
        <>
          <Header
            toggleDarkMode={toggleDarkMode}
            darkMode={darkMode}
            toggleSidebar={toggleSidebar}
          />
          <Sidebar isActive={sidebarActive} closeSidebar={closeSidebar} />
        </>
      )}

      <Routes>
        <Route path="/loggedin" element={<DashBoard />} />
        <Route path="/loggedin/courses" element={<Courses />} />
        <Route
          path="/loggedin/student/attendance/:studentId"
          element={<StudentAttendanceHistory />}
        />
        <Route
          path="/loggedin/staff/attendance/:staffId"
          element={<StaffAttendanceHistory />}
        />
        <Route
          path="/loggedin/student/feepayments/:studentId"
          element={<FeePaymentHistory />}
        />
        <Route
          path="/loggedin/student/attendance"
          element={
            role === 'student' ? <AccessDenied /> : <MarkStudentAttendance />
          }
        />
        <Route
          path="/loggedin/staff/attendance"
          element={
            role === 'student' || role === 'teacher' ? (
              <AccessDenied />
            ) : (
              <MarkStaffAttendance />
            )
          }
        />
        <Route path="/loggedin/students/list" element={<StudentListByBatch />} />
        <Route path="/loggedin/staff/list" element={<StaffListByRole />} />
        <Route path="/loggedin/upload/banner/form" element={<BannerUploader />} />
        <Route
          path="/loggedin/register"
          element={
            role === 'admin' ? (
              <Register isAdmin={role === 'admin'} />
            ) : (
              <AccessDenied />
            )
          }
        />
        <Route path="/loggedin/myprofile" element={<MyProfile />} />
        <Route path="/loggedin/profile/:id" element={<Profile />} />
        <Route
          path="/loggedin/manage-batches/:teacherId"
          element={<ManageBatches />}
        />
        <Route path="/loggedin/onlinetest/:testid" element={<OnlineMCQTest />} />
        <Route
          path="/loggedin/create/onlinemcqtest"
          element={<OnlineTestForm />}
        />
        <Route path="/loggedin/create/offlinetest" element={<OfflineTestForm />} />
        <Route path="/loggedin/test/mytestslist" element={<OnlinetestsList />} />
        <Route
          path="/loggedin/test/offline/mytestslist"
          element={<OfflinetestsList />}
        />
        <Route
          path="/loggedin/test/addStudentmarks/:testId"
          element={<BulkAddStudentMarks />}
        />
        <Route
          path="/loggedin/test/TestsResults/:testid"
          element={<TestsResults />}
        />
        <Route path="/loggedin/online/fee/payment" element={<OnlineFeePayment />} />
        <Route path="/loggedin/studymaterial/form" element={<StudyMaterialForm />} />
        <Route path="/loggedin/StandardBatchManagement" element={<StandardBatchManagement />} />
        <Route path="/comingsoon" element={<ComingSoon />} />
        <Route path="/loggedin/quiz" element={<Quiz />} />
        <Route path="/loggedin/contact" element={<ContactPage />} />
        <Route
          path="/loggedin/studymaterial/e-book"
          element={<StudyMaterialList materialType="E-Books" />}
        />
        <Route
          path="/loggedin/studymaterial/Notes"
          element={<StudyMaterialList materialType="Notes" />}
        />
        <Route
          path="/loggedin/studymaterial/YT-Videos"
          element={<StudyMaterialList materialType="YT-Videos" />}
        />
        <Route
          path="/loggedin/studymaterial/Previous-question-papers"
          element={<StudyMaterialList materialType="Previous-question-papers" />}
        />
        <Route path="/login" element={isLoggedIn ? <Navigate to="/loggedin/" /> : <Login />} />
        <Route path="*" element={<PageNotFound404 />} />
      </Routes>

      {/* {isLoggedIn && <Footer />} */}
    </div>
  );
};

export default App;
