import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Select from 'react-select';
import { useGlobal } from "../context/GlobalContext";

const UpdateForm = ({ userProfile, userId, isAdmin, onClose, onUpdateSuccess }) => {
  const { API_URL } = useGlobal()

  const [name, setName] = useState(userProfile.name || '');
  const [email, setEmail] = useState(userProfile.email || '');
  const [selectedBatch, setSelectedBatch] = useState(userProfile.batch || '');
  const [teacherBatches, setTeacherBatches] = useState(userProfile.teacherBatches || []);
  const [selectedSubjects, setSelectedSubjects] = useState(userProfile.subjects || []);
  const [personalContactNumber, setPersonalContactNumber] = useState(userProfile.personalContactNumber || '');
  const [emergencyContactNumber, setEmergencyContactNumber] = useState(userProfile.emergencyContactNumber || '');
  const [dateOfBirth, setDateOfBirth] = useState(userProfile.dateOfBirth || '');
  const [gender, setGender] = useState(userProfile.gender || '');
  const [parentName, setParentName] = useState(userProfile.parentName || '');
  const [parentContactNumber, setParentContactNumber] = useState(userProfile.parentContactNumber || '');
  const [relationshipToGuardian, setRelationshipToGuardian] = useState(userProfile.relationshipToGuardian || '');
  const [discount, setDiscount] = useState(userProfile.discount || '');
  const [paidFee, setPaidFee] = useState(userProfile.paidFee || '');
  const [address, setAddress] = useState(userProfile.address || '');
  const [paymentMethod, setPaymentMethod] = useState(userProfile.paymentMethod || '');
  const [salary, setSalary] = useState(userProfile.salary || '');
  const [salaryType, setSalaryType] = useState(userProfile.salaryType || '');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [batches, setBatches] = useState([]);
  
  const role = userProfile.role; // Get role directly from userProfile

  const token = document.cookie
    .split('; ')
    .find(row => row.startsWith('x-auth-token='))
    ?.split('=')[1];

  useEffect(() => {
    const fetchBatches = async () => {
      try {
        const response = await axios.get(`${API_URL}/api/standard/batch`, {
          headers: { 'x-auth-token': token || '' },
        });
        setBatches(response.data);
      } catch (error) {
        console.error('Error fetching batches:', error);
      }
    };

    fetchBatches();
  }, [token]);

  const batchOptions = batches.map((batch) => ({
    value: batch._id,
    label: `${batch.name} (${batch.standard.name})`,
  }));

  const getSubjectsFromBatches = () => {
    const selectedBatchObjects = batches.filter((batch) =>
      teacherBatches.includes(batch._id)
    );
    const subjects = selectedBatchObjects.flatMap(
      (batch) => batch.standard.subjects
    );
    const uniqueSubjects = Array.from(new Set(subjects));

    return uniqueSubjects.map((subject) => ({
      value: subject,
      label: subject,
    }));
  };

  const handleTeacherBatchSelection = (selectedOptions) => {
    setTeacherBatches(selectedOptions ? selectedOptions.map((option) => option.value) : []);
    setSelectedSubjects([]);
  };

  const handleSubjectSelection = (selectedOptions) => {
    setSelectedSubjects(selectedOptions ? selectedOptions.map((option) => option.value) : []);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      setPasswordError('Passwords do not match');
      return;
    }

    const data = {
      name,
      email,
      personalContactNumber,
      emergencyContactNumber,
      dateOfBirth,
      gender,
      address,
      password, // Include password in data only if it is set
    };

    if (role === 'student') {
      data.batch = selectedBatch;
      data.discount = discount;
      data.parentName = parentName;
      data.parentContactNumber = parentContactNumber;
      data.relationshipToGuardian = relationshipToGuardian;
      data.paidFee = paidFee;
      data.paymentMethod = paymentMethod;
    }

    if (role === 'teacher') {
      data.teacherBatches = teacherBatches;
      data.subjects = selectedSubjects;
    }

    if (role === 'teacher' || role === 'admin') {
      data.salary = salary;
      data.salaryType = salaryType;
    }

    try {
      await axios.put(`${API_URL}/api/users/profile/${userId}`, data, {
        headers: { 'x-auth-token': token || '' },
      });
      alert('User updated successfully!');
      onUpdateSuccess(true);
      onClose();
    } catch (error) {
      console.error('Error updating user:', error);
      alert('Failed to update user.');
    }
  };

  if (!isAdmin) return <p>You do not have permission to update user details.</p>;

  return (
    <section className="form-container">
      <form onSubmit={handleSubmit}>
        <h3>Update User Details</h3>
        <p>Name</p>
        <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="box" />

        <p>Email</p>
        <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="box" />

        {role === 'student' && (
          <>
            <p>Select Batch</p>
            <select value={selectedBatch} onChange={(e) => setSelectedBatch(e.target.value)} className="box">
              <option value="">Select Batch</option>
              {batches.map(batch => (
                <option key={batch._id} value={batch._id}>{batch.name} ({batch.standard.name})</option>
              ))}
            </select>

            <p>Discount</p>
            <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="box" />

            <p>Parent's Name</p>
            <input type="text" value={parentName} onChange={(e) => setParentName(e.target.value)} className="box" />

            <p>Parent's Contact Number</p>
            <input type="number" value={parentContactNumber} onChange={(e) => setParentContactNumber(e.target.value)} className="box" />

            <p>Relationship to Guardian</p>
            <input type="text" value={relationshipToGuardian} onChange={(e) => setRelationshipToGuardian(e.target.value)} className="box" />

          </>
        )}

        {role === 'teacher' && (
          <>
            <p>Select Batches</p>
            <Select
              options={batchOptions}
              isMulti
              value={batchOptions.filter(option => teacherBatches.includes(option.value))}
              onChange={handleTeacherBatchSelection}
              className="multi-select-dropdown"
              closeMenuOnSelect={false}
            />

            <p>Select Subjects</p>
            <Select
              options={getSubjectsFromBatches()}
              isMulti
              value={getSubjectsFromBatches().filter(option => selectedSubjects.includes(option.value))}
              onChange={handleSubjectSelection}
              className="multi-select-dropdown"
              closeMenuOnSelect={false}
            />
          </>
        )}

        {role !== 'student' && (
          <>
            <p>Salary</p>
            <input type="number" value={salary} onChange={(e) => setSalary(e.target.value)} className="box" />

            <p>Salary Type</p>
            <select value={salaryType} onChange={(e) => setSalaryType(e.target.value)} className="box">
              <option value="">Select Salary Type</option>
              <option value="hourly">Hourly</option>
              <option value="monthly">Monthly</option>
              <option value="project-based">Project-Based</option>
            </select>
          </>
        )}

        <p>Password</p>
        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="box" />

        <p>Confirm Password</p>
        <input
          type="password"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
          className="box"
        />
        {passwordError && <p className="error">{passwordError}</p>}

        <p>Gender</p>
        <select value={gender} onChange={(e) => setGender(e.target.value)} className="box">
          <option value="">Select Gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>

        <p>Address</p>
        <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} className="box" />

        <button type="submit" className="btn">Update</button>
      </form>
    </section>
  );
};

export default UpdateForm;
