import React, { useState, useEffect } from "react";
import axios from "axios";
import Cookies from "js-cookie";
import {
  Box,
  Typography,
  Button,
  Paper,
  IconButton,
  Grid,
  Dialog,
  DialogTitle,
  DialogContent,
  TextField,
  Select,
  MenuItem,
  DialogActions,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import CloseIcon from "@mui/icons-material/Close";
import { useGlobal } from "../context/GlobalContext";
import { toast } from "react-toastify";

const BatchStandard = () => {
  const { API_URL } = useGlobal();

  const [standards, setStandards] = useState([]);
  const [batches, setBatches] = useState([]);
  const [currentItem, setCurrentItem] = useState(null);
  const [formType, setFormType] = useState(""); // "standard" or "batch"
  const [isFormOpen, setIsFormOpen] = useState(false);

  // Function to get the auth token from cookies
  const getAuthToken = () => Cookies.get("x-auth-token");

  // Axios instance with auth token attached
  const axiosWithAuth = axios.create({
    baseURL: API_URL,
    headers: {
      "x-auth-token": getAuthToken(),
    },
  });

  // Fetch standards and batches
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [standardsRes, batchesRes] = await Promise.all([
          axiosWithAuth.get("/api/standard"),
          axiosWithAuth.get("/api/standard/batch"),
        ]);

        setStandards(standardsRes.data || []);
        setBatches(batchesRes.data || []);
      } catch (error) {
        toast.error("Error fetching data!");
        console.error(error);
      }
    };

    fetchData();
  }, [API_URL]);

  const openForm = (item = null, type) => {
    setCurrentItem(item);
    setFormType(type);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setCurrentItem(null);
    setFormType("");
    setIsFormOpen(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const data = Object.fromEntries(formData.entries());

    try {
      if (formType === "standard") {
        data.subjects = data.subjects.split(",");

        if (currentItem) {
          const response = await axiosWithAuth.put(`/api/standard/${currentItem._id}`, data);
          setStandards((prev) =>
            prev.map((std) => (std._id === currentItem._id ? response.data : std))
          );
          toast.success("Standard updated successfully!");
        } else {
          const response = await axiosWithAuth.post("/api/standard", data);
          setStandards((prev) => [...prev, response.data]);
          toast.success("Standard added successfully!");
        }
      } else if (formType === "batch") {
        if (currentItem) {
          const response = await axiosWithAuth.put(`/api/standard/batch/${currentItem._id}`, data);
          setBatches((prev) =>
            prev.map((batch) => (batch._id === currentItem._id ? response.data : batch))
          );
          toast.success("Batch updated successfully!");
        } else {
          const response = await axiosWithAuth.post("/api/standard/batch", data);
          setBatches((prev) => [...prev, response.data]);
          toast.success("Batch added successfully!");
        }
      }
    } catch (error) {
      toast.error("Error submitting data!");
      console.error(error);
    }

    closeForm();
  };

  const handleDelete = async (id, type) => {
    try {
      if (type === "standard") {
        await axiosWithAuth.delete(`/api/standard/${id}`);
        setStandards((prev) => prev.filter((std) => std._id !== id));
        toast.success("Standard deleted successfully!");
      } else if (type === "batch") {
        await axiosWithAuth.delete(`/api/standard/batch/${id}`);
        setBatches((prev) => prev.filter((batch) => batch._id !== id));
        toast.success("Batch deleted successfully!");
      }
    } catch (error) {
      toast.error("Error deleting item!");
      console.error(error);
    }
  };

  return (
    <Box sx={{ padding: 4, maxWidth: "1200px", margin: "0 auto" }}>
      <Typography variant="h4" align="center" gutterBottom>
        Standard and Batch Management
      </Typography>

      <Grid container spacing={4}>
        {/* Standards Section */}
        <Grid item xs={12} md={6}>
          <Paper elevation={3} sx={{ padding: 2 }}>
            <Typography variant="h5" gutterBottom>
              Standards
            </Typography>
            <Box>
              {standards.map((standard) => (
                <Paper
                  key={standard._id}
                  elevation={1}
                  sx={{ padding: 2, marginBottom: 2 }}
                >
                  <Typography variant="subtitle1">
                    <strong>{standard.name}</strong>
                  </Typography>
                  <Typography variant="body2">
                    Subjects: {standard.subjects.join(", ")}
                  </Typography>
                  <Typography variant="body2">Fee: ₹{standard.fee}</Typography>
                  <Box sx={{ marginTop: 1 }}>
                    <IconButton
                      color="primary"
                      onClick={() => openForm(standard, "standard")}
                    >
                      <EditIcon />
                    </IconButton>
                    <IconButton
                      color="error"
                      onClick={() => handleDelete(standard._id, "standard")}
                    >
                      <DeleteIcon />
                    </IconButton>
                  </Box>
                </Paper>
              ))}
            </Box>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => openForm(null, "standard")}
              sx={{ marginTop: 2 }}
            >
              Add Standard
            </Button>
          </Paper>
        </Grid>

        {/* Batches Section */}
        <Grid item xs={12} md={6}>
          <Paper elevation={3} sx={{ padding: 2 }}>
            <Typography variant="h5" gutterBottom>
              Batches
            </Typography>
            <Box>
              {batches.map((batch) => (
                <Paper
                  key={batch._id}
                  elevation={1}
                  sx={{ padding: 2, marginBottom: 2 }}
                >
                  <Typography variant="subtitle1">
                    <strong>{batch.name}</strong>
                  </Typography>
                  <Typography variant="body2">
                    Standard: {batch.standard?.name || "N/A"}
                  </Typography>
                  <Typography variant="body2">
                    Time: {batch.startTime} - {batch.endTime}
                  </Typography>
                  <Box sx={{ marginTop: 1 }}>
                    <IconButton
                      color="primary"
                      onClick={() => openForm(batch, "batch")}
                    >
                      <EditIcon />
                    </IconButton>
                    <IconButton
                      color="error"
                      onClick={() => handleDelete(batch._id, "batch")}
                    >
                      <DeleteIcon />
                    </IconButton>
                  </Box>
                </Paper>
              ))}
            </Box>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => openForm(null, "batch")}
              sx={{ marginTop: 2 }}
            >
              Add Batch
            </Button>
          </Paper>
        </Grid>
      </Grid>

      {/* Dialog Form */}
      <Dialog open={isFormOpen} onClose={closeForm} fullWidth>
        <DialogTitle>
          {currentItem ? `Edit ${formType}` : `Add ${formType}`}
          <IconButton
            aria-label="close"
            onClick={closeForm}
            sx={{
              position: "absolute",
              right: 8,
              top: 8,
            }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <form onSubmit={handleSubmit}>
          <DialogContent>
            {formType === "standard" ? (
              <>
                <TextField
                  label="Name"
                  name="name"
                  fullWidth
                  defaultValue={currentItem?.name || ""}
                  required
                  margin="normal"
                />
                <TextField
                  label="Subjects (comma-separated)"
                  name="subjects"
                  fullWidth
                  defaultValue={currentItem?.subjects?.join(", ") || ""}
                  margin="normal"
                />
                <TextField
                  label="Fee"
                  name="fee"
                  type="number"
                  fullWidth
                  defaultValue={currentItem?.fee || ""}
                  required
                  margin="normal"
                />
              </>
            ) : (
              <>
                <TextField
                  label="Name"
                  name="name"
                  fullWidth
                  defaultValue={currentItem?.name || ""}
                  required
                  margin="normal"
                />
                <Select
                  name="standard"
                  fullWidth
                  default
                  value={currentItem?.standard?._id || ""}
                  required
                  margin="normal"
                >
                  {standards.map((standard) => (
                    <MenuItem key={standard._id} value={standard._id}>
                      {standard.name}
                    </MenuItem>
                  ))}
                </Select>
                <TextField
                  label="Start Time"
                  name="startTime"
                  type="time"
                  fullWidth
                  defaultValue={currentItem?.startTime || ""}
                  required
                  margin="normal"
                />
                <TextField
                  label="End Time"
                  name="endTime"
                  type="time"
                  fullWidth
                  defaultValue={currentItem?.endTime || ""}
                  required
                  margin="normal"
                />
              </>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={closeForm} color="secondary">
              Cancel
            </Button>
            <Button type="submit" color="primary">
              {currentItem ? "Save Changes" : "Add"}
            </Button>
          </DialogActions>
        </form>
      </Dialog>
    </Box>
  );
};

export default BatchStandard;
